package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.parseName
 */
public class TarUtils_parseName_TriageGen1Test {

    @Test
    public void testParseName_NormalString() {
        byte[] buffer = "testfile.txt".getBytes();
        String result = TarUtils.parseName(buffer, 0, buffer.length);
        assertEquals("testfile.txt", result);
    }

    @Test
    public void testParseName_WithNullTerminatorInMiddle() {
        // The method should stop parsing when it encounters a 0 byte
        byte[] buffer = new byte[]{'a', 'b', 0, 'c', 'd'};
        String result = TarUtils.parseName(buffer, 0, buffer.length);
        assertEquals("ab", result);
    }

    @Test
    public void testParseName_WithNullTerminatorAtEnd() {
        byte[] buffer = new byte[]{'h', 'e', 'l', 'l', 'o', 0};
        String result = TarUtils.parseName(buffer, 0, buffer.length);
        assertEquals("hello", result);
    }

    @Test
    public void testParseName_WithOffset() {
        byte[] buffer = new byte[]{0, 0, 'o', 'f', 'f', 's', 'e', 't', 0};
        // Start at index 2, length 5 ('offset')
        String result = TarUtils.parseName(buffer, 2, 5);
        assertEquals("offset", result);
    }

    @Test
    public void testParseName_WithLimitedLength() {
        // Even if there is no null terminator, it must respect the 'length' parameter
        byte[] buffer = "abcdefg".getBytes();
        String result = TarUtils.parseName(buffer, 0, 3);
        assertEquals("abc", result);
    }

    @Test
    public void testParseName_EmptyBuffer() {
        byte[] buffer = new byte[0];
        String result = TarUtils.parseName(buffer, 0, 0);
        assertEquals("", result);
    }

    @Test
    public void testParseName_AllZeros() {
        byte[] buffer = new byte[]{0, 0, 0};
        String result = TarUtils.parseName(buffer, 0, 3);
        assertEquals("", result);
    }

    @Test
    public void testParseName_SingleByte() {
        byte[] buffer = new byte[]{'z'};
        String result = TarUtils.parseName(buffer, 0, 1);
        assertEquals("z", result);
    }

    @Test
    public void testParseName_OffsetAndLengthBoundary() {
        byte[] buffer = new byte[]{'a', 'b', 'c', 'd', 'e'};
        // offset 2 ('c'), length 2 ('cd')
        String result = TarUtils.parseName(buffer, 2, 2);
        assertEquals("cd", result);
    }
}
